        END LOOP;


        FOR i_4 IN 0 TO 504 LOOP
          IF (i_4 + 8) >= to_signed(16#00000009#, 32) THEN 
            bs_6(i_4 + 7) := bs1_4(i_4 - 1);
          END IF;
