        FOR bm1_6 IN 0 TO 7 LOOP
          cast_7(bm1_6) := unsigned(to_signed(bm1_6, 32));
          mask_5 := to_signed(16#01#, 8) sll to_integer(cast_7(bm1_6));
          IF bs_6(511 - bm1_6) = '1' THEN 
            a1_21(bm1_6) := resize(a1_6, 32) OR resize(mask_5, 32);
            a1_6 := a1_21(bm1_6)(7 DOWNTO 0);
          ELSE 
            a1_20(bm1_6) := resize(a1_6, 32) AND resize( NOT mask_5, 32);
            a1_6 := a1_20(bm1_6)(7 DOWNTO 0);
          END IF;
        END LOOP;


        FOR t_10 IN 0 TO 511 LOOP
          bs_7(t_10) := '0';
          bs1_5(t_10) := bs_6(t_10);
