        FOR t_11 IN 0 TO 511 LOOP
          bs_8(t_11) := '0';
          bs1_6(t_11) := bs_7(t_11);
        END LOOP;


        FOR i_6 IN 0 TO 480 LOOP
          IF (i_6 + 32) >= to_signed(16#00000021#, 32) THEN 
            bs_8(i_6 + 31) := bs1_6(i_6 - 1);
          END IF;
        END LOOP;

        a1_8 := payloadConst_src1Addr_unsigned;

        FOR bm1_8 IN 0 TO 31 LOOP
          cast_9(bm1_8) := unsigned(to_signed(bm1_8, 32));
          mask_7 := to_unsigned(16#00000001#, 32) sll to_integer(cast_9(bm1_8));
          IF bs_8(511 - bm1_8) = '1' THEN 
