          IF bs_9(511 - bm1_9) = '1' THEN 
            a1_9 := a1_9 OR mask_8;
          ELSE 
            a1_9 := a1_9 AND ( NOT mask_8);
          END IF;
        END LOOP;

        enq <= '1';
      END IF;
      IF cmd_cmd = LST THEN 
