      END IF;
      deqCmd <= '1';
    END IF;
    IF (cmdValid AND ( NOT wrMode)) = '1' THEN 
      IF cmd_cmd = CLR THEN 
        clear <= '1';
        wrModeNext <= '1';
        wrModeEn <= '1';
      END IF;
      deqCmd <= '1';
    END IF;
    payload_src0Addr_tmp <= a1_9;
    payload_src1Addr_tmp <= a1_8;
    payload_dstAddr_tmp <= a1_7;
    payload_exponent_tmp <= a1_6;
    payload_exponentIn1_tmp <= a1_5;
    payload_exponentIn2_tmp <= a1_4;
    payload_reluValue_tmp <= a1_3;
    payload_reluScaleExp_tmp <= a1_2;
    payload_single2Int8Exp_tmp <= a1_1;
